es{width:min(900px,100%);display:grid;gap:22px}.pdf-page{position:relative;background:#fff;box-shadow:0 8px 30px rgba(16,24,40,.10);border:1px solid #e4e7ec;line-height:0;scroll-margin-top:88px}.pdf-page canvas{display:block;width:100%;height:auto}.text-layer{position:absolute;inset:0;overflow:hidden;opacity:.01;line-height:1;pointer-events:auto;user-select:text}.text-layer span{position:absolute;white-space:pre;transform-origin:0 0;color:#000;cursor:text}.text-layer ::selection{background:rgba(99,102,241,.35)}.reader-mark{background:rgba(250,204,21,.48);border-radius:2px}.reader-loading,.reader-message{width:min(900px,100%);background:#fff;border:1px solid #eaecf0;border-radius:16px;padding:45px;text-align:center;box-sizing:border-box}.reader-message .ds-icon{margin:auto;display:block;color:#667085}.reader-message strong,.reader-message span,.reader-loading strong,.reader-loading span{display:block}.reader-message span,.reader-loading span{font-size:10px;color:#98a2b3;margin-top:8px}.loading-spinner{width:28px;height:28px;border:3px solid #e4e7ec;border-top-color:#4f46e5;border-radius:50%;margin:0 auto 14px;animation:spin .8s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.reader-lock{width:min(900px,100%);margin-top:22px;position:sticky;bottom:18px;padding:20px 22px;background:rgba(255,255,255,.97);backdrop-filter:blur(12px);border:1px solid #e4e7ec;border-radius:16px;box-shadow:0 12px 36px rgba(16,24,40,.12);display:flex;align-items:center;gap:14px;z-index:20;box-sizing:border-box}.lock-icon{width:42px;height:42px;border-radius:12px;background:#eef2ff;display:grid;place-items:center;flex:0 0 auto}.lock-icon .ds-icon{color:#4f46e5}.lock-kicker{font-size:9px;color:#4f46e5;font-weight:700}.reader-lock h2{font-size:14px;margin:4px 0}.reader-lock p{font-size:9px;color:#667085;margin:0}.buy-btn{margin-right:auto;display:inline-flex;align-items:center;gap:6px;padding:10px 15px;border-radius:9px;background:#4f46e5;color:#fff;text-decoration:none;font-size:1