@push('scripts')
@if($pdfFile)
<script type="module">
import * as pdfjsLib from 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.min.mjs';
pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.worker.min.mjs';
(()=>{const shell=document.querySelector('.reader-shell'),pagesBox=document.getElementById('pdfPages'),thumbs=document.getElementById('thumbnailList'),loading=document.getElementById('pdfLoading'),message=document.getElementById('pdfMessage'),current=document.getElementById('currentPage'),count=document.getElementById('pageCount'),zoomValue=document.getElementById('zoomValue');const preview=shell.dataset.preview==='1',maxPages=preview?7:Infinity,url=shell.dataset.pdfUrl;let pdf=null,scale=1,rendered=new Map();
const fail=t=>{loading?.remove();message.hidden=false;message.innerHTML='<strong>'+t+'</strong><span>اگر مشکل ادامه داشت، صفحه را تازه‌سازی کنید.</span>'};
const renderPage=async n=>{if(rendered.has(n)||!pdf)return;const page=await pdf.getPage(n),box=document.createElement('article');box.className='pdf-page';box.id='pdf-page-'+n;box.dataset.page=n;const viewport=page.getViewport({scale}),canvas=document.createElement('canvas'),ctx=canvas.getContext('2d');canvas.width=Math.ceil(viewport.width);canvas.height=Math.ceil(viewport.height);box.appendChild(canvas);pagesBox.appendChild(box);await page.render({canvasContext:ctx,viewport}).promise;try{const tc=await page.getTextContent(),layer=document.createElement('div');layer.className='text-layer';layer.style.width=viewport.width+'px';layer.style.height=viewport.height+'px';tc.items.forEach(item=>{const span=document.createElement('span');span.textContent=item.str;const tx=pdfjsLib.Util.transform(viewport.transform,item.transform),fontHeight=Math.hypot(tx[2],tx[3]);span.style.left=tx[4]+'px';span.style.top=(tx[5]-fontHeight)+'px';span.style.fontSize=fontHeight+'px';span.style.transform='scaleX('+(Math.max(.1,tx[0]/Math.max(fontHeight,.1)))+')';layer.appendChild(span)});box.appendChild(layer)}catch(e){}rendered.set(n,box)};
const buildThumb=async n=>{const page=await pdf.getPage(n),v=page.getViewport({scale:.18}),b=document.createElement('button');b.type='button';b.className='thumb';b.dataset.page=n;const c=document.createElement('canvas'),x=c.getContext('2d');c.width=v.width;c.height=v.height;b.appendChild(c);const s=document.createElement('span');s.textContent='صفحه '+n;b.appendChild(s);await page.render({canvasContext:x,viewport:v}).promise;b.onclick=()=>document.getElementById('pdf-page-'+n)?.scrollIntoView({behavior:'smooth',block:'start'});thumbs.appendChild(b)};
const observe=()=>{const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){const n=+e.target.dataset.page;current.textContent=n;document.querySelectorAll('.thumb').forEach(t=>t.classList.toggle('active',+t.dataset.page===n));if(pdf&&n<Math.min(pdf.numPages,maxPages))renderPage(n+1)}}),{threshold:.45});document.querySelectorAll('.pdf-page').forEach(p=>io.observe(p))};
const rerender=async()=>{pagesBox.innerHTML='';rendered.clear();await renderPage(1);if(pdf&&pdf.numPages>1)await renderPage(2);observe()};
const load=async()=>{try{pdf=await pdfjsLib.getDocument({url}).promise;const visible=Math.min(pdf.numPages,maxPages);count.textContent=preview&&pdf.numPages>7?'7 از '+pdf.numPages:pdf.numPages;loading.remove();for(let i=1;i<=visible;i++)await buildThumb(i);await renderPage(1);if(visible>1)await renderPage(2);observe();if(preview&&pdf.numPages>7){const note=document.createElement('div');note.className='reader-message';note.innerHTML='<strong>پیش‌نمایش به ۷ صفحه محدود شده است.</strong><span>برای ادامه مطالعه، محصول را خریداری کنید.</span>';pagesBox.appendChild(note)}}catch(e){console.error(e);fail('PDF Viewer نتوانست فایل را باز کند.')}};
document.querySelector('[data-action="zoom-in"]')?.addEventListener('click',async()=>{scale=Math.min(2,scale+.1);zoomValue.textContent=Math.round(scale*100)+'%';await rerender()});document.querySelector('[data-action="zoom-out"]')?.addEventListener('click',async()=>{scale=Math.max(.6,scale-.1);zoomValue.textContent=Math.round(scale*100)+'%';await rerender()});document.querySelector('[data-action="next"]')?.addEventListener('click',()=>{const n=Math.min(pdf?.numPages||1,+current.textContent+1);if(n<=maxPages)document.getElementById('pdf-page-'+n)?.scrollIntoView({behavior:'smooth',block:'start'})});document.querySelector('[data-action="prev"]')?.addEventListener('click',()=>{const n=Math.max(1,+current.textContent-1);document.getElementById('pdf-page-'+n)?.scrollIntoView({behavior:'smooth',block:'start'})});document.querySelector('[data-action="highlight"]')?.addEventListener('click',()=>{const s=window.getSelection();if(!s||s.isCollapsed)return;const r=s.getRangeAt(0);if(!r.commonAncestorContainer.parentElement?.closest('.text-layer'))return;try{const mark=document.createElement('mark');mark.className='reader-mark';r.surroundContents(mark)}catch(e){}});document.querySelector('[data-action="note"]')?.addEventListener('click',()=>{const text=prompt('یادداشت شما برای صفحه '+current.textContent+':');if(!text)return;const key='reader-note:'+shell.dataset.product,notes=JSON.parse(localStorage.getItem(key)||'[]');notes.push({page:+current.textContent,text,at:Date.now()});localStorage.setItem(key,JSON.stringify(notes));alert('یادداشت ذخیره شد.')});load()})();
</script>
@endif
@endpush
